{
  "title": "The Mirror's Passage",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined city gates.",
      "visual_description": "A colossal iron gate stands half-collapsed, wrapped in torn royal banners. The glass diver stands before it, his helmet reflecting the shattered towers beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer unfolds her map on a broken wall.",
      "visual_description": "Mara kneels beside a toppled stone wall, pressing wrinkled parchment flat with ink-stained fingers as the tin fox peers over her shoulder.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers a warning about the cursed tower.",
      "visual_description": "Inside a dim alley, the oracle lamp's single flame-eye glows bright as it casts light on a crooked tower in the distance. Its metal base trembles.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts ahead and reports armored patrols.",
      "visual_description": "The tiny clockwork fox crouches behind a crumbling fountain, its blue glass eyes fixed on a line of figures in dark armor marching past.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Mara traces a secret route past the castle gates.",
      "visual_description": "Mara's compass needle spins as she draws a line on her map, the path leading through a collapsed archway near the castle's main gate.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "The sleeping tax collector dozes on a ledger pile.",
      "visual_description": "In an abandoned guardhouse, the sleeping tax collector snores softly, head pillowed on a stack of stamped papers, a quill still tucked behind his ear.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "The glass diver peers through a window into the throne room.",
      "visual_description": "Pressing his helmet against a grimy window, the glass diver sees overturned thrones and scattered banners inside, his own reflection rippling on the glass.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Rumors of a great beast are heard in the market square.",
      "visual_description": "A few frightened figures whisper near empty stalls, the oracle lamp held high among them, casting long shadows as they speak of something in the sky.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The tin fox discovers a hidden magic door.",
      "visual_description": "The fox pushes through overgrown ivy to reveal a stone door inscribed with glowing runes, its keyhole pulsing with faint light.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Mara deciphers the door's riddle.",
      "visual_description": "Mara runs her fingers over the runes, mumbling as her compass needle aligns with a hidden pattern, then presses a hidden latch.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver swims through the magic door into a mirror hall.",
      "visual_description": "He steps through the door and into a vast hall lined with mirrors, each reflecting a different part of the ruined city. His own image multiplies.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The oracle lamp warns of a trap in the hall.",
      "visual_description": "The lamp's eye widens as a mirror shatters, revealing a hidden corridor, and its voice hisses a warning to avoid the false reflections.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The sleeping tax collector wakes briefly and stamps a map.",
      "visual_description": "Roused by the noise, the tax collector blinks, mechanically stamps a blank paper, and hands it to Mara before falling back asleep.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The tin fox leads the group through a crumbling courtyard.",
      "visual_description": "The fox scurries across cracked flagstones, weaving between fallen pillars, as the others follow under the shadow of a broken royal banner.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver retrieves a key from a locked chest.",
      "visual_description": "Inside a collapsed treasury, the glass diver plunges his arm into a mirror-like chest, pulling out a brass key that glows with the same runic light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The oracle lamp illuminates the path to the escape bridge.",
      "visual_description": "The lamp's light cuts through fog, revealing a stone bridge arching over a dry moat, its far end lost in darkness.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The group races across the bridge under pursuit.",
      "visual_description": "Armored figures pour from the castle gates as Mara, the glass diver, the tin fox, the oracle lamp, and the sleepy tax collector sprint across the bridge, banners flapping.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They escape as the bridge collapses behind them.",
      "visual_description": "The last stone crumbles into the moat as they reach the far side, the ruined city now sealed off. The glass diver's helmet reflects the sunrise.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

